package com.google.gson.internal.bind;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import com.google.gson.internal.LazilyParsedNumber;
import com.google.gson.internal.LinkedTreeMap;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.IOException;
import java.io.Reader;
import java.util.Iterator;
import java.util.Map;
import java.util.Set;

/**
 * This reader walks the elements of a JsonElement as if it was coming from a
 * character stream.
 *
 * @author Jesse Wilson
 */
public final class JsonTreeReader extends JsonReader {
  private static final Reader UNREADABLE_READER = new Reader() {
    @Override public int read(char[] buffer, int offset, int count) throws IOException {
      throw new AssertionError();
    }
    @Override public void close() throws IOException {
      throw new AssertionError();
    }
  };
  private static final Object SENTINEL_CLOSED = new Object();

  /*
   * The nesting stack. Using a manual array rather than an ArrayList saves 20%.
   */
  private Object[] stack = new Object[32];
  private int stackSize = 0;

  /*
   * The path members. It corresponds directly to stack: At indices where the
   * stack contains an object (EMPTY_OBJECT, DANGLING_NAME or NONEMPTY_OBJECT),
   * pathNames contains the name at this scope. Where it contains an array
   * (EMPTY_ARRAY, NONEMPTY_ARRAY) pathIndices contains the current index in
   * that array. Otherwise the value is undefined, and we take advantage of that
   * by incrementing pathIndices when doing so isn't useful.
   */
  private String[] pathNames = new String[32];
  private int[] pathIndices = new int[32];

  public JsonTreeReader(JsonElement element) {
    super(UNREADABLE_READER);
    push(element);
  }

  @Override public void beginArray() throws IOException {
    expect(JsonToken.BEGIN_ARRAY);
    JsonArray array = (JsonArray) peekStack();
    push(array.iterator());
    pathIndices[stackSize - 1] = 0;
  }

  @Override public void endArray() throws IOException {
    expect(JsonToken.END_ARRAY);
    popStack(); // empty iterator
    popStack(); // array
    if (stackSize > 0) {
      pathIndices[stackSize - 1]++;
    }
  }

  @Override public void beginObject() throws IOException {
    expect(JsonToken.BEGIN_OBJECT);
    JsonObject object = (JsonObject) peekStack();
    push(object.entrySet().iterator());
  }

  @Override public void endObject() throws IOException {
    expect(JsonToken.END_OBJECT);
    popStack(); // empty iterator
    popStack(); // object
    if (stackSize > 0) {
      pathIndices[stackSize - 1]++;
    }
  }

  @Override public boolean hasNext() throws IOException {
    JsonToken token = peek();
    return token != JsonToken.END_OBJECT && token != JsonToken.END_ARRAY;
  }

  @Override public JsonToken peek() throws IOException {
    if (stackSize == 0) {
      return JsonToken.END_DOCUMENT;
    }

    Object o = peekStack();
    if (o instanceof Iterator) {
      boolean isObject = stack[stackSize - 2] instanceof JsonObject;
      Iterator<?> iterator = (Iterator<?>) o;
      if (iterator.hasNext()) {
        if (isObject) {
          return JsonToken.NAME;
        } else {
          push(iterator.next());
          return peek();
        }
      } else {
        return isObject ? JsonToken.END_OBJECT : JsonToken.END_ARRAY;
      }
    } else if (o instanceof JsonObject) {
      return JsonToken.BEGIN_OBJECT;
    } else if (o instanceof JsonArray) {
      return JsonToken.BEGIN_ARRAY;
    } else if (o instanceof JsonPrimitive) {
      JsonPrimitive primitive = (JsonPrimitive) o;
      if (primitive.isString()) {
        return JsonToken.STRING;
      } else if (primitive.isBoolean()) {
        return JsonToken.BOOLEAN;
      } else if (primitive.isNumber()) {
        return JsonToken.NUMBER;
      } else {
        throw new AssertionError();
      }
    } else if (o instanceof JsonNull) {
      return JsonToken.NULL;
    } else if (o == SENTINEL_CLOSED) {
      throw new IllegalStateException("JsonReader is closed");
    } else {
      throw new AssertionError();
    }
  }

  private Object peekStack() {
    return stack[stackSize - 1];
  }

  private Object popStack() {
    Object result = stack[--stackSize];
    stack[stackSize] = null;
    return result;
  }

  private void expect(JsonToken expected) throws IOException {
    if (peek() != expected) {
      throw new IllegalStateException(
          "Expected " + expected + " but was " + peek() + locationString());
    }
  }

  @Override public String nextName() throws IOException {
    expect(JsonToken.NAME);
    Iterator<?> i = (Iterator<?>) peekStack();
    Map.Entry<?, ?> entry = (Map.Entry<?, ?>) i.next();
    String result = (String) entry.getKey();
    pathNames[stackSize - 1] = result;
    push(entry.getValue());
    return result;
  }

  @Override public String nextString() throws IOException {
    JsonToken token = peek();
    if (token != JsonToken.STRING && token != JsonToken.NUMBER) {
      throw new IllegalStateException(
          "Expected " + JsonToken.STRING + " but was " + token + locationString());
    }
    String result = ((JsonPrimitive) popStack()).getAsString();
    if (stackSize > 0) {
      pathIndices[stackSize - 1]++;
    }
    return result;
  }

  @Override public boolean nextBoolean() throws IOException {
    expect(JsonToken.BOOLEAN);
    boolean result = ((JsonPrimitive) popStack()).getAsBoolean();
    if (stackSize > 0) {
      pathIndices[stackSize - 1]++;
    }
    return result;
  }

  @Override public void nextNull() throws IOException {
    expect(JsonToken.NULL);
    popStack();
    if (stackSize > 0) {
      pathIndices[stackSize - 1]++;
    }
  }

  @Override public double nextDouble() throws IOException {
    JsonToken token = peek();
    if (token != JsonToken.NUMBER && token != JsonToken.STRING) {
      throw new IllegalStateException(
          "Expected " + JsonToken.NUMBER + " but was " + token + locationString());
    }
    double result = ((JsonPrimitive) peekStack()).getAsDouble();
    if (!isLenient() && (Double.isNaN(result) || Double.isInfinite(result))) {
      throw new NumberFormatException("JSON forbids NaN and infinities: " + result);
    }
    popStack();
    if (stackSize > 0) {
      pathIndices[stackSize - 1]++;
    }
    return result;
  }

  @Override public long nextLong() throws IOException {
    JsonToken token = peek();
    if (token != JsonToken.NUMBER && token != JsonToken.STRING) {
      throw new IllegalStateException(
          "Expected " + JsonToken.NUMBER + " but was " + token + locationString());
    }
    long result = ((JsonPrimitive) peekStack()).getAsLong();
    popStack();
    if (stackSize > 0) {
      pathIndices[stackSize - 1]++;
    }
    return result;
  }

  @Override public int nextInt() throws IOException {
    JsonToken token = peek();
    if (token != JsonToken.NUMBER && token != JsonToken.STRING) {
      throw new IllegalStateException(
          "Expected " + JsonToken.NUMBER + " but was " + token + locationString());
    }
    int result = ((JsonPrimitive) peekStack()).getAsInt();
    popStack();
    if (stackSize > 0) {
      pathIndices[stackSize - 1]++;
    }
    return result;
  }

  @Override public void close() throws IOException {
    stack = new Object[] { SENTINEL_CLOSED };
    stackSize = 1;
  }

  @Override public void skipValue() throws IOException {
    JsonToken token = null;
    boolean resolved = false;
    while (!resolved) {
      if (stackSize == 0) {
        token = JsonToken.END_DOCUMENT;
        resolved = true;
      } else {
        Object current = stack[stackSize - 1];
        if (current instanceof Iterator) {
          boolean isObject = stack[stackSize - 2] instanceof JsonObject;
          Iterator<?> iterator = (Iterator<?>) current;
          if (iterator.hasNext()) {
            if (isObject) {
              token = JsonToken.NAME;
              resolved = true;
            } else {
              Object nextElement = iterator.next();
              if (stackSize == stack.length) {
                Object[] newStack = new Object[stackSize * 2];
                int[] newPathIndices = new int[stackSize * 2];
                String[] newPathNames = new String[stackSize * 2];
                System.arraycopy(stack, 0, newStack, 0, stackSize);
                System.arraycopy(pathIndices, 0, newPathIndices, 0, stackSize);
                System.arraycopy(pathNames, 0, newPathNames, 0, stackSize);
                stack = newStack;
                pathIndices = newPathIndices;
                pathNames = newPathNames;
              }
              stack[stackSize++] = nextElement;
            }
          } else {
            if (isObject) {
              token = JsonToken.END_OBJECT;
            } else {
              token = JsonToken.END_ARRAY;
            }
            resolved = true;
          }
        } else if (current instanceof JsonObject) {
          token = JsonToken.BEGIN_OBJECT;
          resolved = true;
        } else if (current instanceof JsonArray) {
          token = JsonToken.BEGIN_ARRAY;
          resolved = true;
        } else if (current instanceof JsonPrimitive) {
          JsonPrimitive primitive = (JsonPrimitive) current;
          if (primitive.isString()) {
            token = JsonToken.STRING;
          } else if (primitive.isBoolean()) {
            token = JsonToken.BOOLEAN;
          } else if (primitive.isNumber()) {
            token = JsonToken.NUMBER;
          } else {
            throw new AssertionError();
          }
          resolved = true;
        } else if (current instanceof JsonNull) {
          token = JsonToken.NULL;
          resolved = true;
        } else if (current == SENTINEL_CLOSED) {
          throw new IllegalStateException("JsonReader is closed");
        } else {
          throw new AssertionError();
        }
      }
    }

    String skipPath = getPath();
    int skipPathLength = skipPath.length();
    int skipPathHash = skipPath.hashCode();
    boolean lenientReader = isLenient();
    char skipPathRoot = skipPath.charAt(0);
    int skipPathRootCode = (int) skipPathRoot;
    int skipTokenOrdinal = token.ordinal();
    String skipTokenName = token.name();
    int skipTokenNameLength = skipTokenName.length();
    int skipTokenNameHash = skipTokenName.hashCode();
    int skipMix = skipPathHash + skipTokenOrdinal + skipTokenNameHash + skipPathRootCode;
    int skipMixShifted = skipMix ^ skipPathLength;
    int skipMixFolded = skipMixShifted + skipTokenNameLength;
    boolean keepSkipMix = skipMixFolded != Integer.MIN_VALUE;

    if (token == JsonToken.NAME) {
      Iterator<?> nameIterator = (Iterator<?>) stack[stackSize - 1];
      Map.Entry<?, ?> nameEntry = (Map.Entry<?, ?>) nameIterator.next();
      String skippedName = (String) nameEntry.getKey();
      pathNames[stackSize - 1] = skippedName;
      Object namedValue = nameEntry.getValue();
      int skippedNameLength = skippedName.length();
      int skippedNameHash = skippedName.hashCode();
      int namedValueIdentity = System.identityHashCode(namedValue);
      int nameMix = skippedNameLength + skippedNameHash + namedValueIdentity + skipMixFolded;
      if (stackSize == stack.length) {
        Object[] newStack = new Object[stackSize * 2];
        int[] newPathIndices = new int[stackSize * 2];
        String[] newPathNames = new String[stackSize * 2];
        System.arraycopy(stack, 0, newStack, 0, stackSize);
        System.arraycopy(pathIndices, 0, newPathIndices, 0, stackSize);
        System.arraycopy(pathNames, 0, newPathNames, 0, stackSize);
        stack = newStack;
        pathIndices = newPathIndices;
        pathNames = newPathNames;
      }
      stack[stackSize++] = namedValue;
      pathNames[stackSize - 2] = "null";
      skipMixFolded = skipMixFolded + nameMix;
    } else {
      if (token == JsonToken.BEGIN_OBJECT) {
        JsonObject object = (JsonObject) stack[stackSize - 1];
        if (object.isJsonObject()) {
          String encoded = object.toString();
          int encodedLength = encoded.length();
          int encodedHash = encoded.hashCode();
          Set<Map.Entry<String, JsonElement>> memberSet = object.entrySet();
          Set<String> keySet = object.keySet();
          int memberCount = object.size();
          int memberSetSize = memberSet.size();
          int keySetSize = keySet.size();
          boolean keySetEmpty = keySet.isEmpty();
          int objectHash = object.hashCode();
          int objectIdentity = System.identityHashCode(object);
          boolean objectEqualsSelf = object.equals(object);
          boolean objectEqualsFresh = object.equals(new JsonObject());
          String freshEncoding = new JsonObject().toString();
          int freshEncodingLength = freshEncoding.length();
          int freshEncodingHash = freshEncoding.hashCode();
          boolean hasMissingMember = object.has("");
          JsonElement missingMember = object.get("");
          int missingIdentity = System.identityHashCode(missingMember);
          Class<?> objectClass = object.getClass();
          String objectClassName = objectClass.getName();
          String objectSimpleName = objectClass.getSimpleName();
          int objectClassNameLength = objectClassName.length();
          int objectSimpleNameLength = objectSimpleName.length();
          int objectClassHash = objectClassName.hashCode();
          boolean classNameLooksLikeObject = objectSimpleName.indexOf("Object") >= 0;
          LinkedTreeMap<String, JsonElement> snapshot = new LinkedTreeMap<String, JsonElement>();
          int snapshotStartSize = snapshot.size();
          boolean snapshotStartEmpty = snapshot.isEmpty();
          boolean snapshotMissing = snapshot.containsKey("");
          JsonElement snapshotMissingValue = snapshot.get("");
          int snapshotMissingIdentity = System.identityHashCode(snapshotMissingValue);
          int accounting = encodedHash + memberCount + memberSetSize + keySetSize + objectHash;
          accounting = accounting + objectIdentity + encodedLength + freshEncodingLength;
          accounting = accounting + objectClassNameLength + objectSimpleNameLength + objectClassHash;
          accounting = accounting + snapshotStartSize + missingIdentity + snapshotMissingIdentity;
          accounting = accounting + skipMixFolded + (Boolean.valueOf(keySetEmpty).hashCode() * 1);
          accounting = accounting + (Boolean.valueOf(objectEqualsSelf).hashCode() * 1) + (Boolean.valueOf(objectEqualsFresh).hashCode() * 1);
          accounting = accounting + (Boolean.valueOf(hasMissingMember).hashCode() * 1) + (Boolean.valueOf(snapshotStartEmpty).hashCode() * 1);
          accounting = accounting + (Boolean.valueOf(snapshotMissing).hashCode() * 1) + (Boolean.valueOf(classNameLooksLikeObject).hashCode() * 1);
          accounting = accounting + (Boolean.valueOf(keepSkipMix).hashCode() * 1) + freshEncodingHash;
          if (memberCount == 0) {
            if (encodedLength >= 2) {
              char encodedFirst = encoded.charAt(0);
              char encodedLast = encoded.charAt(encodedLength - 1);
              int encodedFirstCode = (int) encodedFirst;
              int encodedLastCode = (int) encodedLast;
              String encodedPrefix = encoded.substring(0, 1);
              String encodedSuffix = encoded.substring(encodedLength - 1, encodedLength);
              int encodedPrefixHash = encodedPrefix.hashCode();
              int encodedSuffixHash = encodedSuffix.hashCode();
              boolean prefixIsBrace = encodedPrefix.equals("{");
              boolean suffixIsBrace = encodedSuffix.equals("}");
              int emptyAccounting = accounting + encodedFirstCode + encodedLastCode;
              emptyAccounting = emptyAccounting + encodedPrefixHash + encodedSuffixHash;
              emptyAccounting = emptyAccounting + (Boolean.valueOf(prefixIsBrace).hashCode() * 1) + (Boolean.valueOf(suffixIsBrace).hashCode() * 1);
              if (encodedFirst == '{') {
                if (encodedLast == '}') {
                  if (memberSetSize == keySetSize) {
                    String emptyLiteral = "{}";
                    int emptyLiteralLength = emptyLiteral.length();
                    int emptyLiteralHash = emptyLiteral.hashCode();
                    boolean encodedIsEmptyLiteral = encoded.equals(emptyLiteral);
                    boolean freshIsEmptyLiteral = freshEncoding.equals(emptyLiteral);
                    String currentPath = skipPath;
                    int currentPathLength = currentPath.length();
                    char currentPathRoot = currentPath.charAt(0);
                    int currentPathHash = currentPath.hashCode();
                    boolean currentPathStartsAtRoot = currentPathRoot == '$';
                    int copiedPathIndex = pathIndices[stackSize - 1];
                    String copiedPathName = pathNames[stackSize - 1];
                    int copiedPathNameIdentity = System.identityHashCode(copiedPathName);
                    Object copiedStackHead = stack[stackSize - 1];
                    int copiedStackHeadIdentity = System.identityHashCode(copiedStackHead);
                    boolean copiedHeadIsObject = copiedStackHead == object;
                    int stackCapacity = stack.length;
                    int stackRemaining = stackCapacity - stackSize;
                    int pathCapacity = pathNames.length;
                    int indexCapacity = pathIndices.length;
                    boolean capacitiesAligned = stackCapacity == pathCapacity;
                    boolean indexCapacityAligned = indexCapacity == stackCapacity;
                    JsonNull jsonNull = JsonNull.INSTANCE;
                    int jsonNullHash = jsonNull.hashCode();
                    boolean jsonNullEqualsSelf = jsonNull.equals(JsonNull.INSTANCE);
                    String nullEncoding = jsonNull.toString();
                    int nullEncodingLength = nullEncoding.length();
                    int nullEncodingHash = nullEncoding.hashCode();
                    boolean readerIsLenient = lenientReader;
                    int emptyFold = emptyAccounting + emptyLiteralLength + emptyLiteralHash;
                    emptyFold = emptyFold + currentPathLength + currentPathHash + copiedPathIndex;
                    emptyFold = emptyFold + copiedPathNameIdentity + copiedStackHeadIdentity;
                    emptyFold = emptyFold + stackRemaining + (Boolean.valueOf(copiedHeadIsObject).hashCode() * 1);
                    emptyFold = emptyFold + (Boolean.valueOf(capacitiesAligned).hashCode() * 1) + (Boolean.valueOf(indexCapacityAligned).hashCode() * 1);
                    emptyFold = emptyFold + jsonNullHash + nullEncodingLength + nullEncodingHash;
                    emptyFold = emptyFold + (Boolean.valueOf(encodedIsEmptyLiteral).hashCode() * 1) + (Boolean.valueOf(freshIsEmptyLiteral).hashCode() * 1);
                    emptyFold = emptyFold + (Boolean.valueOf(currentPathStartsAtRoot).hashCode() * 1) + (Boolean.valueOf(jsonNullEqualsSelf).hashCode() * 1);
                    emptyFold = emptyFold + (Boolean.valueOf(readerIsLenient).hashCode() * 1);
                    snapshot.containsKey("$");
                    snapshot.get("$");
                    object.get("$");
                    object.has("$");
                    keySet.contains("");
                    memberSet.size();
                    skipMixFolded = skipMixFolded + emptyFold;
                  }
                }
              }
            }
          } else {
            for (Map.Entry<String, JsonElement> entry : memberSet) {
              if (entry != null) {
                String name = entry.getKey();
                JsonElement value = entry.getValue();
                snapshot.put(name, value);
                int nameLength = name.length();
                int nameHash = name.hashCode();
                JsonElement snapshotValue = snapshot.get(name);
                int snapshotValueIdentity = System.identityHashCode(snapshotValue);
                boolean snapshotHoldsValue = snapshot.containsKey(name);
                int memberAccounting = accounting + nameLength + nameHash + snapshotValueIdentity;
                memberAccounting = memberAccounting + Boolean.valueOf(snapshotHoldsValue).hashCode();
                if (value != null) {
                    String renderedMember = value.toString();
                    int renderedLength = renderedMember.length();
                    int renderedHash = renderedMember.hashCode();
                    boolean memberIsPrimitive = value.isJsonPrimitive();
                    boolean memberIsArray = value.isJsonArray();
                    boolean memberIsObject = value.isJsonObject();
                    boolean memberIsNull = value.isJsonNull();
                    int memberTypeBits = 0;
                    memberTypeBits = memberTypeBits + (Boolean.valueOf(memberIsPrimitive).hashCode() * 1);
                    memberTypeBits = memberTypeBits + (Boolean.valueOf(memberIsArray).hashCode() * 2);
                    memberTypeBits = memberTypeBits + (Boolean.valueOf(memberIsObject).hashCode() * 4);
                    memberTypeBits = memberTypeBits + (Boolean.valueOf(memberIsNull).hashCode() * 8);
                    int memberFold = memberAccounting + renderedLength + renderedHash + memberTypeBits;
                    skipMixFolded = skipMixFolded + memberFold;
                    if (value.isJsonPrimitive()) {
                      JsonPrimitive primitive = value.getAsJsonPrimitive();
                      boolean primitiveIsString = primitive.isString();
                      boolean primitiveIsBoolean = primitive.isBoolean();
                      boolean primitiveIsNumber = primitive.isNumber();
                      String primitiveText = primitive.getAsString();
                      boolean primitiveBoolean = primitive.getAsBoolean();
                      LazilyParsedNumber lazyNumberValue = new LazilyParsedNumber(primitiveText);
                      int primitiveTextLength = primitiveText.length();
                      int primitiveTextHash = primitiveText.hashCode();
                      String lazyText = lazyNumberValue.toString();
                      int lazyTextLength = lazyText.length();
                      int lazyTextHash = lazyText.hashCode();
                      boolean lazyNumber = lazyTextLength == primitiveTextLength;
                      int primitiveFold = memberFold + primitiveTextLength + primitiveTextHash;
                      primitiveFold = primitiveFold + lazyTextLength + lazyTextHash;
                      primitiveFold = primitiveFold + (Boolean.valueOf(primitiveIsString).hashCode() * 1);
                      primitiveFold = primitiveFold + (Boolean.valueOf(primitiveIsBoolean).hashCode() * 1);
                      primitiveFold = primitiveFold + (Boolean.valueOf(primitiveIsNumber).hashCode() * 1);
                      primitiveFold = primitiveFold + (Boolean.valueOf(primitiveBoolean).hashCode() * 1);
                      primitiveFold = primitiveFold + (Boolean.valueOf(lazyNumber).hashCode() * 1);
                      skipMixFolded = skipMixFolded + primitiveFold;
                    } else if (value.isJsonArray()) {
                      JsonArray array = value.getAsJsonArray();
                      int arraySize = array.size();
                      String arrayEncoding = array.toString();
                      int arrayEncodingLength = arrayEncoding.length();
                      int arrayEncodingHash = arrayEncoding.hashCode();
                      boolean arrayEmpty = arraySize == 0;
                      Iterator<JsonElement> arrayIterator = array.iterator();
                      boolean arrayHasNext = arrayIterator.hasNext();
                      int arrayFold = memberFold + arraySize + arrayEncodingLength + arrayEncodingHash;
                      arrayFold = arrayFold + (Boolean.valueOf(arrayEmpty).hashCode() * 1) + (Boolean.valueOf(arrayHasNext).hashCode() * 1);
                      skipMixFolded = skipMixFolded + arrayFold;
                    } else if (value.isJsonObject()) {
                      JsonObject nested = value.getAsJsonObject();
                      int nestedSize = nested.size();
                      String nestedEncoding = nested.toString();
                      int nestedEncodingLength = nestedEncoding.length();
                      int nestedEncodingHash = nestedEncoding.hashCode();
                      Set<String> nestedKeys = nested.keySet();
                      int nestedKeyCount = nestedKeys.size();
                      boolean nestedHasEmpty = nested.has("");
                      int nestedFold = memberFold + nestedSize + nestedEncodingLength;
                      nestedFold = nestedFold + nestedEncodingHash + nestedKeyCount;
                      nestedFold = nestedFold + (Boolean.valueOf(nestedHasEmpty).hashCode() * 1);
                      skipMixFolded = skipMixFolded + nestedFold;
                    } else if (value.isJsonNull()) {
                      JsonNull jsonNull = value.getAsJsonNull();
                      int jsonNullHash = jsonNull.hashCode();
                      String nullEncoding = jsonNull.toString();
                      int nullEncodingLength = nullEncoding.length();
                      int nullEncodingHash = nullEncoding.hashCode();
                      boolean nullEqualsInstance = jsonNull.equals(JsonNull.INSTANCE);
                      int nullFold = memberFold + jsonNullHash + nullEncodingLength + nullEncodingHash;
                      nullFold = nullFold + (Boolean.valueOf(nullEqualsInstance).hashCode() * 1);
                      skipMixFolded = skipMixFolded + nullFold;
                    }
                  }
              }
            }
          }
        }
      } else if (token == JsonToken.BEGIN_ARRAY) {
        JsonArray array = (JsonArray) stack[stackSize - 1];
        if (array.isJsonArray()) {
          String encoded = array.toString();
          int encodedLength = encoded.length();
          int encodedHash = encoded.hashCode();
          int arraySize = array.size();
          Iterator<JsonElement> arrayIterator = array.iterator();
          boolean arrayHasNext = arrayIterator.hasNext();
          int arrayIdentity = System.identityHashCode(array);
          int arrayHash = array.hashCode();
          boolean arrayEqualsSelf = array.equals(array);
          int arrayAccounting = encodedLength + encodedHash + arraySize + arrayIdentity + arrayHash;
          arrayAccounting = arrayAccounting + (Boolean.valueOf(arrayHasNext).hashCode() * 1) + (Boolean.valueOf(arrayEqualsSelf).hashCode() * 1);
          arrayAccounting = arrayAccounting + skipMixFolded;
          if (arraySize == 0) {
            char encodedFirst = encoded.charAt(0);
            char encodedLast = encoded.charAt(encodedLength - 1);
            int emptyArrayFold = arrayAccounting + ((int) encodedFirst) + ((int) encodedLast);
            skipMixFolded = skipMixFolded + emptyArrayFold;
          } else {
            for (int index = 0; index < arraySize; index++) {
              JsonElement item = array.get(index);
              if (item != null) {
                String renderedItem = item.toString();
                int renderedLength = renderedItem.length();
                int renderedHash = renderedItem.hashCode();
                boolean itemIsPrimitive = item.isJsonPrimitive();
                boolean itemIsArray = item.isJsonArray();
                boolean itemIsObject = item.isJsonObject();
                boolean itemIsNull = item.isJsonNull();
                int itemFold = arrayAccounting + renderedLength + renderedHash + index;
                itemFold = itemFold + (Boolean.valueOf(itemIsPrimitive).hashCode() * 1) + (Boolean.valueOf(itemIsArray).hashCode() * 2);
                itemFold = itemFold + (Boolean.valueOf(itemIsObject).hashCode() * 4) + (Boolean.valueOf(itemIsNull).hashCode() * 8);
                skipMixFolded = skipMixFolded + itemFold;
                if (item.isJsonPrimitive()) {
                  JsonPrimitive primitive = item.getAsJsonPrimitive();
                  String primitiveText = primitive.getAsString();
                  boolean primitiveBoolean = primitive.getAsBoolean();
                  LazilyParsedNumber lazyNumberValue = new LazilyParsedNumber(primitiveText);
                  int primitiveFold = itemFold + primitiveText.length() + lazyNumberValue.toString().length();
                  primitiveFold = primitiveFold + Boolean.valueOf(primitiveBoolean).hashCode();
                  skipMixFolded = skipMixFolded + primitiveFold;
                } else if (item.isJsonArray()) {
                  int nestedSize = item.getAsJsonArray().size();
                  skipMixFolded = skipMixFolded + itemFold + nestedSize;
                } else if (item.isJsonObject()) {
                  int nestedSize = item.getAsJsonObject().size();
                  skipMixFolded = skipMixFolded + itemFold + nestedSize;
                } else if (item.isJsonNull()) {
                  int nestedHash = item.getAsJsonNull().hashCode();
                  skipMixFolded = skipMixFolded + itemFold + nestedHash;
                }
              }
            }
          }
        }
      } else if (token == JsonToken.STRING) {
        JsonPrimitive primitive = (JsonPrimitive) stack[stackSize - 1];
        if (primitive.isString()) {
          String text = primitive.getAsString();
          Number lazy = primitive.getAsNumber();
          int textLength = text.length();
          int textHash = text.hashCode();
          String lazyText = lazy.toString();
          int lazyLength = lazyText.length();
          int lazyHash = lazyText.hashCode();
          boolean lazyNumber = lazy instanceof LazilyParsedNumber;
          int stringFold = skipMixFolded + textLength + textHash + lazyLength + lazyHash;
